use std::{fs, path::{Path, PathBuf}};
use thiserror::Error;
const MAX_FILE_BYTES: usize = 1024 * 1024;
#[derive(Clone, Debug)] pub struct FileAuthority { pub root: PathBuf, pub allow_write: bool }
#[derive(Clone, Debug)] pub struct ProjectFiles { authority: FileAuthority }
impl ProjectFiles { pub fn new(authority: FileAuthority) -> Result<Self, FileToolError> { let root = fs::canonicalize(&authority.root)?; if !root.is_dir() { return Err(FileToolError::OutsideRoot); } Ok(Self { authority: FileAuthority { root, ..authority } }) } fn resolve(&self, relative: &Path) -> Result<PathBuf, FileToolError> { if relative.is_absolute() { return Err(FileToolError::OutsideRoot); } let candidate = self.authority.root.join(relative); let canonical = fs::canonicalize(candidate)?; if canonical.starts_with(&self.authority.root) { Ok(canonical) } else { Err(FileToolError::OutsideRoot) } } pub fn read(&self, path: impl AsRef<Path>) -> Result<Vec<u8>, FileToolError> { let body = fs::read(self.resolve(path.as_ref())?)?; if body.len() > MAX_FILE_BYTES { return Err(FileToolError::TooLarge); } Ok(body) } pub fn search(&self, path: impl AsRef<Path>, needle: &str) -> Result<Vec<usize>, FileToolError> { let text = String::from_utf8(self.read(path)?).map_err(|_| FileToolError::NotText)?; Ok(text.match_indices(needle).map(|(index, _)| index).take(1024).collect()) } pub fn edit(&self, path: impl AsRef<Path>, expected: &[u8], replacement: &[u8]) -> Result<(), FileToolError> { if !self.authority.allow_write { return Err(FileToolError::WriteDenied); } if replacement.len() > MAX_FILE_BYTES { return Err(FileToolError::TooLarge); } let path = self.resolve(path.as_ref())?; let current = fs::read(&path)?; if current != expected { return Err(FileToolError::Conflict); } fs::write(path, replacement)?; Ok(()) } }
#[derive(Debug, Error)] pub enum FileToolError { #[error("file I/O failed: {0}")] Io(#[from] std::io::Error), #[error("path is outside configured roots")] OutsideRoot, #[error("file exceeds bound")] TooLarge, #[error("file is not UTF-8 text")] NotText, #[error("write authority denied")] WriteDenied, #[error("optimistic content identity conflict")] Conflict }
